            put( "stp_cancelled", "canceled" );
            put( "reduce_only_expired", "canceled" );
            put( "parent_cancelled", "canceled" );
            put( "position_closed", "canceled" );
            put( "position_flipped", "canceled" );
            put( "reduce_only_invalid_at_trigger", "canceled" );
            put( "order_expired", "expired" );
