    public String parseTransactionStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "pending", "pending" );
            put( "confirmed", "ok" );
            put( "removed", "failed" );
            put( "failed", "failed" );
        }};
        return this.safeString(statuses, status, status);
    }

    public Object parseTransaction(Map<String, Object> transaction, Map<String, Object> currency)
    {
        //
        // deposit row
        //
        //     {
        //         "hash": "0x...",
        //         "asset": "USDC",
        //         "amount": "100",
        //         "from": "0x...",
        //         "to": "0x...",
        //         "status": "confirmed",
        //         "confirmations": 10,
        //         "required_confirmations": 10,
        //         "created_timestamp": 1788546565789,
        //         "confirmed_timestamp": 1788546570789
        //     }
        //
        // withdrawal row
        //
        //     {
        //         "withdraw_id": 123,
        //         "asset": "USDC",
        //         "amount": "100",
        //         "to": "0x...",
        //         "fee": "0.1",
        //         "status": "pending",
        //         "hash": "0x",
        //         "confirmations": 0,
        //         "required_confirmations": 10,
        //         "created_timestamp": 1788546565789
        //     }
        //
        String withdrawId = this.safeString(transaction, "withdraw_id");
        String type = (((!java.util.Objects.equals(withdrawId, null)))) ? "withdrawal" : "deposit";
        String currencyId = this.safeString(transaction, "asset");
        String code = this.safeCurrencyCode(currencyId, currency);
        Long timestamp = this.safeInteger(transaction, "created_timestamp");
        String rawHash = this.safeString(transaction, "hash");
        // the venue reports the literal 0x prefix while the transaction is unmined
        String txid = (((java.util.Objects.equals(rawHash, "0x")))) ? null : rawHash;
        String feeCost = this.safeString(transaction, "fee");
        Map<String, Object> fee = null;
        if (!java.util.Objects.equals(feeCost, null))
        {
            {
                HashMap<String, Object> hx4NewMap2 = new HashMap<String, Object>();
                hx4NewMap2.put("cost", this.parseNumber(feeCost));
                hx4NewMap2.put("currency", code);
                fee = hx4NewMap2;
            }
        }
        {
            HashMap<String, Object> h2kMap1 = new HashMap<String, Object>();
            h2kMap1.put("info", transaction);
            h2kMap1.put("id", withdrawId);
            h2kMap1.put("txid", txid);
            h2kMap1.put("timestamp", timestamp);
            h2kMap1.put("datetime", this.iso8601(timestamp));
            h2kMap1.put("network", null);
            h2kMap1.put("address", null);
            h2kMap1.put("addressTo", this.safeString(transaction, "to"));
            h2kMap1.put("addressFrom", this.safeString(transaction, "from"));
            h2kMap1.put("tag", null);
            h2kMap1.put("tagTo", null);
            h2kMap1.put("tagFrom", null);
            h2kMap1.put("type", type);
            h2kMap1.put("amount", this.safeNumber(transaction, "amount", (Object) null));
            h2kMap1.put("currency", code);
            h2kMap1.put("status", this.parseTransactionStatus(this.safeString(transaction, "status")));
            h2kMap1.put("updated", this.safeInteger(transaction, "confirmed_timestamp"));
            h2kMap1.put("comment", null);
            h2kMap1.put("internal", false);
            h2kMap1.put("fee", fee);
            return h2kMap1;
        }
    }

